package com.vasiliyrogozhin85.upospa;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;
public class HistoryActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);UiKit.screen(this);setContentView(ui());}private View ui(){ScrollView s=new ScrollView(this);s.setBackgroundColor(UiKit.BG);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(UiKit.dp(this,16),UiKit.dp(this,16),UiKit.dp(this,16),UiKit.dp(this,24));s.addView(r);TextView h=UiKit.tv(this,"‹  История устройств",25,UiKit.TEXT,true);h.setOnClickListener(v->finish());r.addView(h);JSONArray a=new DeviceHistoryStore(this).load();if(a.length()==0)r.addView(UiKit.card(this,UiKit.tv(this,"История пока пуста. Создайте диагностический отчёт.",14,UiKit.MUTED,false)),UiKit.top(this,12));for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x==null)continue;LinearLayout c=UiKit.card(this);c.addView(UiKit.tv(this,x.optString("manufacturer")+" "+x.optString("model"),16,UiKit.TEXT,true));c.addView(UiKit.tv(this,x.optString("time")+" • Android "+x.optString("android")+" • "+x.optString("source"),12,UiKit.MUTED,false),UiKit.top(this,4));r.addView(c,UiKit.top(this,8));}r.addView(UiKit.button(this,"Очистить историю",UiKit.ERROR,v->{new DeviceHistoryStore(this).clear();recreate();}));return s;}}
